#!/usr/bin/env python3
"""Generate the one-colour launcher and notification versions of the document icon."""
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
DRAWABLE = ROOT / "app/src/main/res/drawable"
DOCUMENT_PATH = (
    "M34,18 h27 l17,17 v48 q0,4 -4,4 h-40 q-4,0 -4,-4 v-61 q0,-4 4,-4 z "
    "M61,18 v17 h17 z "
    "M42,45 h27 v5 h-27 z "
    "M42,57 h22 v5 h-22 z "
    "M42,69 h17 v5 h-17 z"
)


def vector(width: int, height: int, color: str) -> str:
    return f"""<?xml version="1.0" encoding="utf-8"?>
<!-- Generated by scripts/make-monochrome-icon.py from the Office Lite document mark. -->
<vector xmlns:android="http://schemas.android.com/apk/res/android"
    android:width="{width}dp"
    android:height="{height}dp"
    android:viewportWidth="108"
    android:viewportHeight="108">
    <path
        android:fillColor="{color}"
        android:fillType="evenOdd"
        android:pathData="{DOCUMENT_PATH}" />
</vector>
"""


def main() -> None:
    (DRAWABLE / "ic_launcher_monochrome.xml").write_text(
        vector(108, 108, "#FF000000")
    )
    (DRAWABLE / "ic_notification.xml").write_text(
        vector(24, 24, "#FFFFFFFF")
    )


if __name__ == "__main__":
    main()
